{
  "root_causes": [
    {
      "service": "ts-station-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, round(approx_quantile(duration/1e6,0.5),1) p50ms FROM abnormal_traces WHERE service_name='ts-station-service' AND span_name='SELECT station' GROUP BY ALL", "claim": "Station's 'SELECT station' DB spans error after about 30 s (pool timeout) in the incident, while normal calls take about 0.5 ms."},
        {"kind": "log", "sql": "SELECT service_name, level, substr(message,1,120) msg, count(*) n FROM abnormal_logs WHERE service_name='ts-station-service' AND level IN ('ERROR','SEVERE','WARN') GROUP BY 1,2,3 ORDER BY n DESC", "claim": "Station logs HikariPool 'Connection is not available, request timed out after 30000ms' and MySQL 'Communications link failure' errors."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(CASE WHEN p='a' THEN value END),2) abn_avg, round(avg(CASE WHEN p='n' THEN value END),2) norm_avg FROM (SELECT 'a' p, * FROM abnormal_metrics UNION ALL SELECT 'n', * FROM normal_metrics) WHERE service_name='ts-station-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1", "claim": "Station CPU and memory stay at or below normal levels, so the failure is not resource saturation."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-station-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_http_response_status_code>=400 THEN 1 ELSE 0 END) callee_4xx5xx, round(approx_quantile(c.duration/1e6,0.5),1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-basic-service' AND c.service_name='ts-station-service' GROUP BY 1,2", "claim": "Basic's calls to station return 403 after about 30 s, 4 of 9 calls errored."}]},
