    {"from": "ts-basic-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration/1e6,0.5),1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel2-service' AND c.service_name='ts-basic-service' GROUP BY 1,2", "claim": "Travel2's calls to basic are slowed, with server p50 about 16 ms versus normal."}]},
